defmodule JoobQ.Worker.HeartbeatTest do
  use ExUnit.Case, async: true

  alias JoobQ.Worker.{Heartbeater, Leases}

  test "a lease is renewed every third of its lifetime, at least every 500 ms" do
    assert Heartbeater.every(30_000) == 10_000
    assert Heartbeater.every(1_000) == 500
  end

  test "a failed renewal is made again only while the next round is not due" do
    assert Heartbeater.again?(0, 250, 10_000)
    refute Heartbeater.again?(9_900, 250, 10_000)
  end

  test "a handler's own beat is due once per window, and never for a lease not held" do
    assert Leases.due?(nil, 5, 100)
    assert Leases.due?(0, 100, 100)
    refute Leases.due?(50, 100, 100)

    name = :"beats_#{System.unique_integer([:positive])}"
    refute Leases.beat_due?(name, "a", 100)
    Leases.new(name)
    Leases.hold(name, ["a"])
    assert Leases.beat_due?(name, "a", 60_000)
    refute Leases.beat_due?(name, "a", 60_000)
    refute Leases.beat_due?(name, "b", 60_000)
  end

  test "JoobQ.Job.heartbeat/1 answers the cached cancellation without a call" do
    name = :"beats_#{System.unique_integer([:positive])}"
    Leases.new(name)
    Leases.hold(name, ["a", "b"])
    Leases.cancelled(name, "a")

    assert JoobQ.Job.heartbeat(%JoobQ.Job{instance: name, lease_token: "a"})
    refute JoobQ.Job.heartbeat(%JoobQ.Job{instance: name, lease_token: "b"})
    refute JoobQ.Job.heartbeat(%JoobQ.Job{instance: :nothing_started, lease_token: "a"})
  end
end
